import { useCallback, useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [view, setView] = useState({ results: [], phase: "idle" });

  const valueRef = useRef("");
  const searchRef = useRef(search);
  const timerRef = useRef(null);
  const latestRequestRef = useRef(null);
  const mountedRef = useRef(false);

  const cancelDebounce = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const clearSearch = useCallback(() => {
    cancelDebounce();

    const previous = latestRequestRef.current;
    latestRequestRef.current = null;
    setView({ results: [], phase: "idle" });
    previous?.controller.abort();
  }, [cancelDebounce]);

  const startRequest = useCallback(
    (query, force = false) => {
      cancelDebounce();

      if (!mountedRef.current) return;

      if (query.length < minChars) {
        clearSearch();
        return;
      }

      const previous = latestRequestRef.current;

      if (
        !force &&
        previous &&
        previous.query === query &&
        !previous.controller.signal.aborted &&
        (previous.phase === "pending" || previous.phase === "success")
      ) {
        return;
      }

      const controller = new AbortController();
      const request = { query, controller, phase: "pending" };

      latestRequestRef.current = request;

      const isCurrent = () =>
        mountedRef.current &&
        latestRequestRef.current === request &&
        !controller.signal.aborted;

      setView((current) => ({
        results: current.results,
        phase: "pending",
      }));

      previous?.controller.abort();
      if (!isCurrent()) return;

      const searchFunction = searchRef.current;

      void (async () => {
        try {
          const results = await searchFunction(query, {
            signal: controller.signal,
          });

          if (!isCurrent()) return;

          request.phase = "success";
          setView({ results, phase: "success" });
        } catch (error) {
          if (!isCurrent()) return;

          if (error?.name === "AbortError") {
            request.phase = "aborted";
            setView((current) => ({
              results: current.results,
              phase: "idle",
            }));
          } else {
            request.phase = "error";
            setView({ results: [], phase: "error" });
          }
        }
      })();
    },
    [cancelDebounce, clearSearch, minChars]
  );

  const scheduleRequest = useCallback(
    (rawValue) => {
      cancelDebounce();

      const query = rawValue.trim();

      if (query.length < minChars) {
        clearSearch();
        return;
      }

      timerRef.current = setTimeout(() => {
        timerRef.current = null;
        startRequest(query);
      }, debounceMs);
    },
    [cancelDebounce, clearSearch, debounceMs, minChars, startRequest]
  );

  // Callback changes should not restart an existing debounce.
  useEffect(() => {
    searchRef.current = search;
  }, [search]);

  useEffect(() => {
    mountedRef.current = true;

    return () => {
      mountedRef.current = false;
      cancelDebounce();

      const previous = latestRequestRef.current;
      latestRequestRef.current = null;
      previous?.controller.abort();
    };
  }, [cancelDebounce]);

  // Typing schedules synchronously; this handles mount and configuration changes.
  useEffect(() => {
    scheduleRequest(valueRef.current);
    return cancelDebounce;
  }, [scheduleRequest, cancelDebounce]);

  const handleChange = (event) => {
    const nextValue = event.target.value;
    valueRef.current = nextValue;
    setValue(nextValue);
    scheduleRequest(nextValue);
  };

  const statusText =
    view.phase === "pending"
      ? "Searching..."
      : view.phase === "success" && view.results.length === 0
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{statusText}</div>
      <ul aria-label="Results">
        {view.results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {view.phase === "error" && (
        <div role="alert">
          Something went wrong{" "}
          <button
            type="button"
            onClick={() => startRequest(valueRef.current.trim(), true)}
          >
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
